  /**
   * Which features [What&#39;s new](https://docs.gitlab.com/administration/whats-new/) shows. &#x60;all_tiers&#x60; shows features for all tiers, &#x60;current_tier&#x60; shows only features for the instance&#39;s tier, and &#x60;disabled&#x60; hides What&#39;s new.
   */
  public enum WhatsNewVariantEnum {
    ALL_TIERS(String.valueOf("all_tiers")),
    
    CURRENT_TIER(String.valueOf("current_tier")),
    
    DISABLED(String.valueOf("disabled"));

    private String value;

    WhatsNewVariantEnum(String value) {
      this.value = value;
    }

    @JsonValue
    public String getValue() {
      return value;
    }

    @Override
    public String toString() {
      return String.valueOf(value);
    }

    @JsonCreator
    public static WhatsNewVariantEnum fromValue(String value) {
      for (WhatsNewVariantEnum b : WhatsNewVariantEnum.values()) {
        if (b.value.equals(value)) {
          return b;
        }
      }
      return null;
    }
  }

