  /**
   * Sets the behavior for Sidekiq job size limits. Default: &#39;compress&#39;.
   */
  public enum SidekiqJobLimiterModeEnum {
    TRACK(String.valueOf("track")),
    
    COMPRESS(String.valueOf("compress"));

    private String value;

    SidekiqJobLimiterModeEnum(String value) {
      this.value = value;
    }

    @JsonValue
    public String getValue() {
      return value;
    }

    @Override
    public String toString() {
      return String.valueOf(value);
    }

    @JsonCreator
    public static SidekiqJobLimiterModeEnum fromValue(String value) {
      for (SidekiqJobLimiterModeEnum b : SidekiqJobLimiterModeEnum.values()) {
        if (b.value.equals(value)) {
          return b;
        }
      }
      return null;
    }
  }

