  /**
   * Default review level for GitLab Duo Code Review Flow. One of &#x60;lite&#x60; or &#x60;standard&#x60;. Beta.
   */
  public enum DuoCodeReviewDefaultLevelEnum {
    LITE(String.valueOf("lite")),
    
    STANDARD(String.valueOf("standard"));

    private String value;

    DuoCodeReviewDefaultLevelEnum(String value) {
      this.value = value;
    }

    @JsonValue
    public String getValue() {
      return value;
    }

    @Override
    public String toString() {
      return String.valueOf(value);
    }

    @JsonCreator
    public static DuoCodeReviewDefaultLevelEnum fromValue(String value) {
      for (DuoCodeReviewDefaultLevelEnum b : DuoCodeReviewDefaultLevelEnum.values()) {
        if (b.value.equals(value)) {
          return b;
        }
      }
      return null;
    }
  }

